import java.util.*;
public class ServiceTest { static void eq(Object actual,Object expected){if(!Objects.equals(actual,expected))throw new AssertionError("expected="+expected+" actual="+actual);}static void yes(boolean value){if(!value)throw new AssertionError("contract violated");}public static void main(String[]args)throws Exception{
var s=new Service();yes(s.update(0,"first"));yes(!s.update(0,"stale"));eq(s.value,"first");eq(s.version,1);var winners=new java.util.concurrent.atomic.AtomicInteger();var gate=new java.util.concurrent.CountDownLatch(1);Thread a=new Thread(()->{try{gate.await();if(s.update(1,"a"))winners.incrementAndGet();}catch(Exception e){throw new RuntimeException(e);}});Thread b=new Thread(()->{try{gate.await();if(s.update(1,"b"))winners.incrementAndGet();}catch(Exception e){throw new RuntimeException(e);}});a.start();b.start();gate.countDown();a.join();b.join();eq(winners.get(),1);eq(s.version,2);
System.out.println("PASS business-optimistic-lock");}}
